// 2. BLIND FREQUENCY (Discovery)
const BlindFrequencyView = ({ onBack }: { onBack: () => void }) => {
  const [status, setStatus] = useState<'idle' | 'searching' | 'found'>('idle');
  const [timer, setTimer] = useState(222); // 3:42 in seconds

  useEffect(() => {
    let interval: any;
    if (status === 'found' && timer > 0) {
      interval = setInterval(() => setTimer(t => t - 1), 1000);
    }
    return () => clearInterval(interval);
  }, [status, timer]);

  const startSearch = () => {
    triggerHaptic('heavy');
    setStatus('searching');
    setTimeout(() => {
      triggerHaptic('medium');
      setStatus('found');
    }, 2500);
  };

  const formatTime = (s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m}:${sec < 10 ? '0' : ''}${sec}`;
  };

  if (status === 'found') {
    return (
      <div className="h-full flex flex-col bg-black relative overflow-hidden">
        {/* Signal Found Header */}
        <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-transparent via-cyan-500 to-transparent animate-pulse shadow-[0_0_20px_rgba(34,211,238,0.5)]" />

        <div className="pt-20 px-6 pb-4 flex items-center justify-between bg-black/50 backdrop-blur-sm z-10">
          <div className="flex items-center space-x-2">
             <Signal className="text-cyan-400 animate-pulse" size={16} />
             <span className="text-cyan-400 font-mono text-sm tracking-widest uppercase">Signal Locked</span>
          </div>
          <button onClick={() => setStatus('idle')} className="text-white/40 hover:text-white"><X size={20} /></button>
        </div>

        {/* Content */}
        <div className="flex-1 flex flex-col items-center justify-center relative p-6">
           {/* Background Pulse */}
           <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <div className="w-64 h-64 rounded-full bg-cyan-500/5 blur-[100px] animate-pulse" />
           </div>

           <div className="w-full max-w-sm bg-[#111] border border-cyan-500/20 rounded-2xl p-6 relative z-10 shadow-[0_0_30px_rgba(6,182,212,0.1)]">
              <div className="flex justify-between items-start mb-6">
                 <div>
                    <h3 className="text-white font-bold text-xl">Anonymous User</h3>
                    <p className="text-white/50 text-xs">Vibe match: 94%</p>
                 </div>
                 <div className="px-3 py-1 bg-cyan-900/30 border border-cyan-500/30 rounded-full">
                    <span className="font-mono text-cyan-400 font-bold">{formatTime(timer)}</span>
                 </div>
              </div>

              <div className="h-40 overflow-y-auto mb-4 space-y-3 mask-gradient">
                 <div className="bg-white/5 p-2 rounded-lg rounded-tl-none self-start max-w-[80%]">
                    <p className="text-sm text-white/80">Yo, this bassline is insane.</p>
                 </div>
                 <div className="bg-cyan-500/10 border border-cyan-500/20 p-2 rounded-lg rounded-tr-none self-end max-w-[80%] ml-auto">
                    <p className="text-sm text-cyan-100">Right?? Wait for the bridge.</p>
                 </div>
              </div>

              <div className="flex space-x-2">
                 <input type="text" placeholder="Type a message..." className="flex-1 bg-black/50 border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:border-cyan-500 outline-none transition-colors" />
                 <button className="p-2 bg-cyan-500/20 text-cyan-400 rounded-lg hover:bg-cyan-500 hover:text-black transition-colors">
                    <Send size={18} />
                 </button>
              </div>
           </div>

           <button className="mt-8 px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform shadow-lg shadow-white/10 flex items-center space-x-2">
              <Radio size={18} />
              <span>Keep Signal</span>
           </button>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col items-center justify-center relative bg-black overflow-hidden">
       {/* Background Grid */}
       <div className="absolute inset-0 opacity-20" style={{ backgroundImage: 'linear-gradient(#333 1px, transparent 1px), linear-gradient(90deg, #333 1px, transparent 1px)', backgroundSize: '40px 40px' }} />

       <button onClick={onBack} className="absolute top-20 left-6 text-white/50 hover:text-white z-20">
          <ArrowLeft size={24} />
       </button>

       <div className="relative z-10 flex flex-col items-center">
          <motion.button 
             onClick={startSearch}
             className={`w-48 h-48 rounded-full flex flex-col items-center justify-center border-4 relative transition-all duration-500
                ${status === 'searching' ? 'border-cyan-500 bg-cyan-900/20 scale-110' : 'border-[#FA2D48] bg-white/5 hover:scale-105 hover:bg-white/10'}
             `}
             animate={status === 'searching' ? { boxShadow: "0 0 50px rgba(6,182,212,0.4)" } : {}}
          >
             {status === 'searching' ? (
                <>
                   <div className="absolute inset-0 rounded-full border-4 border-cyan-500 animate-ping opacity-20" />
                   <div className="absolute inset-0 rounded-full border-4 border-cyan-500 animate-ping opacity-10 animation-delay-500" />
                   <Globe size={48} className="text-cyan-400 animate-pulse mb-2" />
