// --- MAIN COMPONENT ---

const Connect: React.FC<ConnectProps> = ({ onPlayTrack }) => {
  const [view, setView] = useState<'hub' | 'blind' | 'room'>('hub');
  const [activeRoomId, setActiveRoomId] = useState<number | null>(null);

  // View Handlers
  const goBlind = () => setView('blind');
  const goRoom = (id: number) => {
    setActiveRoomId(id);
    setView('room');
  };
  const goBack = () => {
    setView('hub');
    setActiveRoomId(null);
  };

  if (view === 'blind') return <BlindFrequencyView onBack={goBack} />;
  if (view === 'room' && activeRoomId) return <RoomDetail roomId={activeRoomId} onLeave={goBack} />;

  return (
    <div className="h-full bg-black relative">
      <div className="h-full overflow-y-auto no-scrollbar bg-black">
        <div className="pt-20 px-6">
          <div className="flex items-center justify-between mb-8">
