            <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-gray-700 to-gray-600 flex items-center justify-center border border-white/10 border-dashed">
               <span className="font-['Caveat'] text-xl font-bold">Me</span>
            </div>
          </div>

          {/* Blind Frequency Card */}
          <section className="mb-10">
            <div 
              onClick={goBlind}
              className="w-full bg-gradient-to-r from-cyan-900/40 to-blue-900/40 border border-cyan-500/20 rounded-2xl p-6 flex items-center justify-between cursor-pointer group hover:border-cyan-500/50 transition-colors relative overflow-hidden"
            >
              <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] opacity-20" />
              <div className="relative z-10">
                 <h2 className="text-2xl font-bold text-white mb-1 flex items-center">
                    Blind Frequency 
                    <Signal size={18} className="ml-2 text-cyan-400 animate-pulse" />
